ee:message.ee:set-payload:
%dw 2.0
output application/json
var records = payload.records default []
---
records map ((contact) -> {
  id: null,
  globalId: null,
  externalIds: [{
    system: "Salesforce",
    value: contact.Id
  }],
  customerNumber: contact.AccountNumber default null,
  party: {
    partyType: "Individual",
    firstName: contact.FirstName default null,
    lastName: contact.LastName default null,
    taxId: contact.TaxId__c default null
  },
  status: contact.Status__c default "Active"
})

%dw 2.0
output application/json
---
{
  error: {
    code: "SALESFORCE_ERROR",
    message: "An error occurred while querying Salesforce",
    timestamp: now()
  }
}

%dw 2.0
output application/json
---
{
  error: {
    code: "SALESFORCE_ERROR",
    message: "An error occurred while upserting customer in Salesforce",
    timestamp: now()
  }
}

%dw 2.0
output application/json
var contact = payload
---
{
  id: null,
  globalId: null,
  externalIds: [{
    system: "Salesforce",
    value: contact.Id
  }],
  customerNumber: contact.AccountNumber default null,
  party: {
    partyType: "Individual",
    firstName: contact.FirstName default null,
    lastName: contact.LastName default null,
    taxId: contact.TaxId__c default null
  },
  status: contact.Status__c default "Active"
}

%dw 2.0
output application/json
---
{
  error: {
    code: "NOT_FOUND",
    message: "Customer not found in Salesforce",
    timestamp: now()
  }
}
